// frontend/src/pages/Login.js
import React, { useState } from 'react';
import { useDispatch } from 'react-redux';
import { setCredentials } from '../features/auth/authSlice';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import { jwtDecode } from 'jwt-decode'; // Correct named import (for v3+)

const Login = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const dispatch = useDispatch();
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    try {
      const response = await axios.post('http://127.0.0.1:8000/api/auth/login/', {
        email,
        password,
      });

      const { access, refresh } = response.data;

      // Store tokens in localStorage (use secure cookies in production)
      localStorage.setItem('access_Token', access);
      localStorage.setItem('refreshToken', refresh);

      // Decode the access token to get user info
      const decoded = jwtDecode(access);

      // Extract user details from token claims
      const user = {
        id: decoded.user_id || decoded.sub || 'unknown', // Adjust based on your JWT claims
        email: decoded.email || email, // Fallback to input email
        is_staff: decoded.is_staff || false, // Will be true if you add custom claim in backend
        // Add more fields as needed (e.g., username, first_name)
      };

      dispatch(setCredentials({ user, token: access }));

      // Redirect based on role
      if (user.is_staff) {
        navigate('/admin');
      } else {
        navigate('/employee');
      }
    } catch (err) {
      console.error('Login error:', err);
      setError('Login failed. Please check your credentials.');
    }
  };

  return (
    <div style={{
      minHeight: '100vh',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
      padding: '20px',
    }}>
      <div style={{
        backgroundColor: 'white',
        padding: '40px',
        borderRadius: '16px',
        boxShadow: '0 10px 30px rgba(0, 0, 0, 0.1)',
        maxWidth: '400px',
        width: '100%',
      }}>
        <h2 style={{ textAlign: 'center', marginBottom: '30px', color: '#333', fontSize: '28px' }}>
          Welcome Back
        </h2>

        {error && (
          <p style={{ color: 'red', textAlign: 'center', marginBottom: '20px', fontSize: '14px' }}>
            {error}
          </p>
        )}

        <form onSubmit={handleSubmit}>
          <div style={{ marginBottom: '20px' }}>
            <label style={{ display: 'block', marginBottom: '8px', color: '#555', fontWeight: '500' }}>
              Email
            </label>
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="Enter your email"
              required
              style={{
                width: '100%',
                padding: '12px',
                border: '1px solid #ddd',
                borderRadius: '8px',
                fontSize: '16px',
                outline: 'none',
                transition: 'border 0.3s',
              }}
              onFocus={(e) => (e.target.style.border = '1px solid #667eea')}
              onBlur={(e) => (e.target.style.border = '1px solid #ddd')}
            />
          </div>

          <div style={{ marginBottom: '30px' }}>
            <label style={{ display: 'block', marginBottom: '8px', color: '#555', fontWeight: '500' }}>
              Password
            </label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="Enter your password"
              required
              style={{
                width: '100%',
                padding: '12px',
                border: '1px solid #ddd',
                borderRadius: '8px',
                fontSize: '16px',
                outline: 'none',
                transition: 'border 0.3s',
              }}
              onFocus={(e) => (e.target.style.border = '1px solid #667eea')}
              onBlur={(e) => (e.target.style.border = '1px solid #ddd')}
            />
          </div>

          <button
            type="submit"
            style={{
              width: '100%',
              padding: '14px',
              backgroundColor: '#667eea',
              color: 'white',
              border: 'none',
              borderRadius: '8px',
              fontSize: '16px',
              fontWeight: '600',
              cursor: 'pointer',
              transition: 'background 0.3s',
            }}
            onMouseOver={(e) => (e.target.style.backgroundColor = '#5a67d8')}
            onMouseOut={(e) => (e.target.style.backgroundColor = '#667eea')}
          >
            Login
          </button>
        </form>
      </div>
    </div>
  );
};

export default Login;
